def kth_largest(nums: list[int], k: int) -> int:
    """
    Implements the Quickselect algorithm to find the k-th largest element
    in an unsorted list. The average time complexity is O(n), while the worst 
    case is O(n^2) in scenarios where the pivot selection results in 
    unbalanced partitions.
    """

    def partition(left, right, pivot_index):
        pivot_value = nums[pivot_index]
        # Move pivot to end
        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]
        store_index = left
        for i in range(left, right):
            if nums[i] > pivot_value:  # Note: '>' for k-th largest
                nums[store_index], nums[i] = nums[i], nums[store_index]
                store_index += 1
